insert into cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-lassen-five-rows-loaded-s651','decision','Lassen: Cal-GETC 34 from its own catalog, five rows reread','The S651 conductor, #3291 (merged 8d6be618): Lassen''s catalog prints Cal-GETC 34 (p.72), a set step. Reread run 43581530119 replaced five rows (30947, 31015, 31037, 31379, 32083), GE units 34; 30947 and 32083 pass (Lassen 35 to 37 of 59). Held: 31297, 35106, 41912; 33388 never fills. Five restored rows need a capture on main''s pages. Receipt holds before-values.',array['program-requirements-harvest','cal-getc','decision'],'proposed','S651 checkpoint; docs/session_652_handoff.md and the lane files',null,null,'SkyDunlin (S651)',date '2026-11-14'),
('p-word-guard-neighbor-page-pass-s651','pitfall','The electives word guard can match on the next program''s page','S651, Lassen 32083: the word guard found elective on p.93, the next program''s page inside the reader''s range, so the row passes. Disclosed on #3291 and left as loaded; COBIx: leave it as loaded, holding it would turn a correct pass into a false fail. He asks for a statewide count of such rows before #3293 changes the rule; the dry run reads the sentence inside the program''s own section.',array['program-requirements-harvest','scorer','pitfall'],'proposed','S651 checkpoint; docs/session_652_handoff.md and the lane files',null,null,'SkyDunlin (S651)',date '2026-11-14'),
('d-display-rule-withdrawn-structured-fields-s651','decision','Display gaps: a text-rewrite rule withdrawn; structured fields instead','The S651 conductor reverted (7f0f1b91) a display rule that led gaps with reconciled words across 724 rows at 26 colleges: a second reader found 225 clean; words holds curator notes, not catalog quotations. The stale-note defect is its own design item: structured fields (figure, its one pattern, source link, basis printed/summed/statewide/borrowed), never quoting words or editing a reader''s note.',array['program-requirements-harvest','display','decision'],'proposed','S651 checkpoint; docs/session_652_handoff.md and the lane files',null,null,'SkyDunlin (S651)',date '2026-11-14'),
('d-passing-dry-run-held-for-cobix-s651','decision','The one dry run for the passing function is posted and held','The S651 conductor, draft #3293 (head cb60a1b0), posted on #3111: nothing applied. Noncredit Total Hours 45 candidates at 12 colleges; the own-list rule not coded (undefined); GE-pattern certificates 89 match, none with quoted evidence, inert; the electives-fill guard fails five live passing records (15,834 to 15,829). The migration and one rescore wait on COBIx''s review.',array['program-requirements-harvest','scorer','decision'],'proposed','S651 checkpoint; docs/session_652_handoff.md and the lane files',null,null,'SkyDunlin (S651)',date '2026-11-14'),
('d-sdccd-objectives-loaded-s651','decision','San Diego district course objectives loaded','The S651 conductor, #3283: load run 43585473767 inserted 2,532 objective rows (San Diego City 698, Mesa 1,151, Miramar 683); the 2,229 SLO rows unchanged; receipt kb/receipts/course_outcomes_sdccd_43585473767.json names every id. The helper never prints load for an objectives reread, so .load is written by hand. Next: sac, laspositas, Coastline, Golden West.',array['program-requirements-harvest','course-outcomes','decision'],'proposed','S651 checkpoint; docs/session_652_handoff.md and the lane files',null,null,'SkyDunlin (S651)',date '2026-11-14'),
('august-2026-transcribed-drop-pierce-s651','fact','The August 2026 drop in transcribed units is Los Angeles Pierce College','S651, plan v2 Q3 on #3111: statewide transcribed units fell on Aug 6 and 7, 2026 (102,591 to 93,289 to 76,262). Pierce alone accounts for it (about 27,700 to about 1,400; loss 26,555 against a statewide net 26,330); Workforce and Other and Apprentice fell, Military flat. Our code and API parameters were unchanged. The MAP team or Pierce can say whether it was a re-upload or a correction.',array['map-custom-reports','live-metrics','fact'],'proposed','S651 checkpoint; docs/session_652_handoff.md and the lane files',null,null,'SkyDunlin (S651)',date '2026-11-14'),
('d-sierra-test-session-ids-excluded-s651','decision','Sierra usage reports exclude the five test session ids','The S651 conductor, plan v2 Q4: Sierra''s test callers use fixed session ids (smoke-ci, health-probe, preflight, sierra-ask-workflow, ab-cap-probe). 30 days of chat_interactions read 09:21Z 2026-11-14: 2,391 turns, 2,146 from those five (smoke-ci 2,024), 245 across 141 other sessions. A report excludes the five ids; an is_test column set by the edge function is a NEXT (needs a deploy).',array['sierra-retrieval-corpus','usage','decision'],'proposed','S651 checkpoint; docs/session_652_handoff.md and the lane files',null,null,'SkyDunlin (S651)',date '2026-11-14'),
('d-strategic-plan-generated-in-commons-builder-s651','decision','The strategic plan file is generated by the Commons status builder','The S651 conductor, plan v2 Q6 on #3111: kb/strategic_plan.json is generated inside kb/_build_commons_status.py, plus one hand-kept file, with a read-only view. Not built. The plan duplicates five of #2919''s items, contradicts none and leaves out seven; a held-from-#2919 list is proposed. COBIx''s answer on Q5 (the Pages traffic archive) is awaited.',array['commons','governance-team-enablement','decision'],'proposed','S651 checkpoint; docs/session_652_handoff.md and the lane files',null,null,'SkyDunlin (S651)',date '2026-11-14')
on conflict (slug) do nothing;
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select id, 'SkyDunlin (S651)', 'create', 'S651 checkpoint (2026-11-14)', to_jsonb(m)
from public.cpl_memory m where m.slug in
  ('d-lassen-five-rows-loaded-s651','p-word-guard-neighbor-page-pass-s651','d-display-rule-withdrawn-structured-fields-s651','d-passing-dry-run-held-for-cobix-s651','d-sdccd-objectives-loaded-s651','august-2026-transcribed-drop-pierce-s651','d-sierra-test-session-ids-excluded-s651','d-strategic-plan-generated-in-commons-builder-s651')
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');
select m.slug, length(m.summary) as summary_chars, count(l.id) filter (where l.action = 'create') as creates
from public.cpl_memory m left join public.cpl_memory_log l on l.memory_id = m.id
where m.slug in
  ('d-lassen-five-rows-loaded-s651','p-word-guard-neighbor-page-pass-s651','d-display-rule-withdrawn-structured-fields-s651','d-passing-dry-run-held-for-cobix-s651','d-sdccd-objectives-loaded-s651','august-2026-transcribed-drop-pierce-s651','d-sierra-test-session-ids-excluded-s651','d-strategic-plan-generated-in-commons-builder-s651')
group by m.slug, m.summary order by m.slug;
